"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { PricingToggle } from "./pricing-toggle";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PRICING CALCULATOR: drag to your size, watch the price
 *
 *   drag      the thumb follows your finger; the fill and a
 *             value bubble ride with it and the price rolls as
 *             you go
 *   jump      click the track (or tap a mark) and the thumb is
 *             thrown there with a little give
 *   tiers     crossing a mark morphs the plan's name and lights
 *             the mark; the button's words follow
 *   contact   past the last tier the price folds away and the
 *             line becomes "Let's talk"
 *   yearly    with a discount, a Monthly/Yearly switch rolls every
 *             figure to its yearly price
 *
 * Bring your own formula: price(value) and plan(value). A real
 * slider: arrow keys, Page Up/Down, Home and End.
 * ───────────────────────────────────────────────────────── */

export interface CalculatorMark {
  value: number;
  label: string;
}

export interface PricingCalculatorProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  min: number;
  max: number;
  step?: number;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** Monthly price for a value, before any yearly discount. */
  price: (value: number) => number;
  /** The plan a value falls in, e.g. "Growth". */
  plan?: (value: number) => string;
  /** Ticks along the track, e.g. where tiers change. */
  marks?: CalculatorMark[];
  /** What's being counted, e.g. "monthly active users". */
  unit?: string;
  /** Intl.NumberFormat options for the value, e.g. { notation: "compact" }. */
  valueFormat?: Intl.NumberFormatOptions;
  currency?: string;
  /** Locale for every figure, e.g. "en-US". Set it when the page is rendered on a server, so both sides format alike. */
  locales?: string | string[];
  /** Evenly spaced orders of magnitude, for ranges like 1,000 to 1,000,000. */
  scale?: "linear" | "log";
  /** At or above this, show "Let's talk" instead of a price. */
  contactFrom?: number;
  /** e.g. 0.2 shows a Monthly/Yearly switch with "Save 20%". */
  yearlyDiscount?: number;
  /** The button under the price; its words follow the plan. */
  cta?: {
    label: (plan: string) => string;
    contactLabel?: string;
    onClick?: (
      value: number,
      plan: string,
      billing: "monthly" | "yearly",
    ) => void;
  };
  label?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function PricingCalculator({
  min,
  max,
  step = 1,
  value: valueProp,
  defaultValue,
  onValueChange,
  price,
  plan = () => "",
  marks = [],
  unit = "",
  valueFormat,
  currency = "USD",
  locales,
  scale = "linear",
  contactFrom,
  yearlyDiscount,
  cta,
  label = "Usage",
  className = "",
  ...props
}: PricingCalculatorProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue ?? min);
  const value = valueProp ?? own;
  const [billing, setBilling] = React.useState<"monthly" | "yearly">("monthly");
  const [dragging, setDragging] = React.useState(false);
  const [thrown, setThrown] = React.useState(false);
  const trackRef = React.useRef<HTMLDivElement>(null);
  const thumbRef = React.useRef<HTMLDivElement>(null);
  const pointer = React.useRef<number | null>(null);

  // Value ↔ position along the track, linear or by orders of magnitude.
  const toRatio = React.useCallback(
    (v: number) => {
      if (scale === "log" && min > 0)
        return (Math.log(v) - Math.log(min)) / (Math.log(max) - Math.log(min));
      return (v - min) / (max - min);
    },
    [scale, min, max],
  );
  const fromRatio = React.useCallback(
    (r: number) => {
      const c = Math.min(1, Math.max(0, r));
      const raw =
        scale === "log" && min > 0
          ? Math.exp(Math.log(min) + c * (Math.log(max) - Math.log(min)))
          : min + c * (max - min);
      // On a log scale, round to a step that suits the size (1,000s near 10k, 10,000s near 100k).
      const s =
        scale === "log"
          ? Math.max(step, 10 ** Math.max(0, Math.floor(Math.log10(raw)) - 1))
          : step;
      return Math.min(max, Math.max(min, Math.round(raw / s) * s));
    },
    [scale, min, max, step],
  );

  const set = (next: number) => {
    const v = Math.min(max, Math.max(min, next));
    if (valueProp === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const fromPointer = (clientX: number) => {
    const track = trackRef.current;
    if (!track) return value;
    const r = track.getBoundingClientRect();
    return fromRatio((clientX - r.left) / r.width);
  };

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0) return;
    e.preventDefault();
    pointer.current = e.pointerId;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    thumbRef.current?.focus({ preventScroll: true });
    // A press away from the thumb throws it there; a press on it starts a drag.
    const onThumb = (e.target as HTMLElement).closest("[data-thumb]");
    setThrown(!onThumb);
    setDragging(Boolean(onThumb));
    set(fromPointer(e.clientX));
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (pointer.current !== e.pointerId) return;
    if (!dragging) {
      setThrown(false);
      setDragging(true);
    }
    set(fromPointer(e.clientX));
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (pointer.current !== e.pointerId) return;
    pointer.current = null;
    setDragging(false);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const r = toRatio(value);
    const nudge = (d: number) => {
      // Each press moves at least one visible step, even where a log scale is coarse.
      const next = fromRatio(r + d);
      return next === value ? value + Math.sign(d) * step : next;
    };
    const moves: Record<string, () => number> = {
      ArrowRight: () => nudge(0.01),
      ArrowUp: () => nudge(0.01),
      ArrowLeft: () => nudge(-0.01),
      ArrowDown: () => nudge(-0.01),
      PageUp: () => nudge(0.1),
      PageDown: () => nudge(-0.1),
      Home: () => min,
      End: () => max,
    };
    if (!(e.key in moves)) return;
    e.preventDefault();
    setThrown(e.key === "Home" || e.key === "End" || e.key.startsWith("Page"));
    set(moves[e.key]());
  };

  const ratio = Math.min(1, Math.max(0, toRatio(value)));
  const contact = contactFrom !== undefined && value >= contactFrom;
  const planName = plan(value);
  const discount = billing === "yearly" && yearlyDiscount ? yearlyDiscount : 0;
  const monthly = price(value) * (1 - discount);
  const currencyFormat = React.useMemo<Intl.NumberFormatOptions>(
    () => ({ style: "currency", currency, maximumFractionDigits: 0 }),
    [currency],
  );
  const valueText = new Intl.NumberFormat(locales, valueFormat).format(value);
  const moveTransition =
    reduced || dragging
      ? "none"
      : thrown
        ? `transform 520ms ${THROW}`
        : `transform 220ms ${EASE}`;
  const fillTransition =
    reduced || dragging
      ? "none"
      : thrown
        ? `transform 520ms ${THROW}`
        : `transform 220ms ${EASE}`;

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div className="min-w-0">
          {/* The plan's name morphs as you cross a tier. */}
          <p className="h-5 text-[13px] font-medium text-primary">
            <TextMorph>{contact ? "Enterprise" : planName}</TextMorph>
          </p>
          <div className="mt-1 flex h-[60px] items-baseline">
            <span
              className="grid"
              style={{
                gridTemplateColumns: contact ? "0fr" : "1fr",
                opacity: contact ? 0 : 1,
                filter: contact ? "blur(6px)" : "none",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 460ms ${EASE}, opacity 300ms ${EASE}, filter 300ms ${EASE}`,
              }}
            >
              <span className="flex min-w-0 items-baseline gap-1 overflow-hidden whitespace-nowrap">
                <NumberRoll
                  value={Math.round(monthly)}
                  format={currencyFormat}
                  locales={locales}
                  className="text-[52px] font-medium leading-none tracking-[-0.04em] text-foreground"
                />
                <span className="text-[15px] text-muted-foreground">/mo</span>
              </span>
            </span>
            <span
              className="grid"
              style={{
                gridTemplateColumns: contact ? "1fr" : "0fr",
                opacity: contact ? 1 : 0,
                filter: contact ? "none" : "blur(6px)",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 460ms ${EASE}, opacity 300ms ${EASE} 120ms, filter 300ms ${EASE} 120ms`,
              }}
            >
              <span className="min-w-0 overflow-hidden whitespace-nowrap text-[52px] font-medium leading-none tracking-[-0.04em] text-foreground">
                Let’s talk
              </span>
            </span>
          </div>
          <p className="mt-2 min-h-5 text-[13px] leading-5 text-muted-foreground">
            <TextMorph animateWidth={false}>
              {contact
                ? "Volume pricing, SSO and a named contact"
                : discount
                  ? `${new Intl.NumberFormat(locales, currencyFormat).format(Math.round(monthly * 12))} billed yearly`
                  : "Billed monthly, cancel anytime"}
            </TextMorph>
          </p>
        </div>
        {yearlyDiscount ? (
          <PricingToggle
            value={billing}
            onValueChange={(v) => setBilling(v as "monthly" | "yearly")}
            options={[
              { value: "monthly", label: "Monthly" },
              {
                value: "yearly",
                label: "Yearly",
                badge: `Save ${Math.round(yearlyDiscount * 100)}%`,
              },
            ]}
          />
        ) : null}
      </div>

      {/* The slider. */}
      <div className="mt-10 select-none">
        <div
          ref={trackRef}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
          className="relative flex h-10 cursor-pointer touch-none items-center"
        >
          <div className="absolute inset-x-0 h-1.5 overflow-hidden rounded-full bg-muted shadow-[inset_0_0_0_1px_var(--border)]">
            <div
              className="h-full origin-left rounded-full bg-primary"
              style={{
                transform: `scaleX(${ratio})`,
                transition: fillTransition,
              }}
            />
          </div>
          {marks.map((m) => {
            const r = toRatio(m.value);
            const passed = value >= m.value;
            return (
              <span
                key={m.value}
                aria-hidden="true"
                className="absolute top-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full transition-[background-color,transform] duration-300"
                style={{
                  left: `${r * 100}%`,
                  background: passed
                    ? "var(--primary-foreground)"
                    : "color-mix(in oklab, var(--foreground) 22%, transparent)",
                }}
              />
            );
          })}
          {/* The thumb, with the value riding above it. The rider ends at the thumb and hangs
              off to the left, so it never widens the page the way a box pushed right would. */}
          <div
            className="pointer-events-none absolute inset-y-0 left-0 w-full"
            style={{
              transform: `translateX(${(ratio - 1) * 100}%)`,
              transition: moveTransition,
            }}
          >
            <div
              ref={thumbRef}
              data-thumb=""
              role="slider"
              tabIndex={0}
              aria-label={label}
              aria-valuemin={min}
              aria-valuemax={max}
              aria-valuenow={value}
              aria-valuetext={`${valueText}${unit ? ` ${unit}` : ""}${contact ? ", contact sales" : `, ${new Intl.NumberFormat(locales, currencyFormat).format(Math.round(monthly))} a month`}`}
              aria-describedby={`${id}-plan`}
              onKeyDown={onKeyDown}
              className={`pointer-events-auto absolute left-full top-1/2 flex size-6 -translate-x-1/2 -translate-y-1/2 cursor-grab items-center justify-center rounded-full bg-background shadow-[0_0_0_1px_var(--border)] outline-none transition-[scale] duration-200 focus-visible:ring-2 focus-visible:ring-ring/40 ${
                dragging ? "scale-110 cursor-grabbing" : ""
              }`}
            >
              <span className="size-2 rounded-full bg-primary" />
              {/* Centred over the thumb mid-track, leaning inwards at the ends so it never leaves the track. */}
              <span
                aria-hidden="true"
                className="absolute bottom-full left-1/2 mb-2.5 flex h-7 items-baseline whitespace-nowrap rounded-full bg-background px-2.5 pt-[5px] text-[12.5px] font-medium tabular-nums text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                style={{
                  transform: `translateX(${-ratio * 100}%)`,
                  transition: moveTransition,
                }}
              >
                <NumberRoll
                  value={value}
                  format={valueFormat}
                  locales={locales}
                  duration={dragging ? 300 : 600}
                />
                {unit && (
                  <span className="ml-1 font-normal text-muted-foreground">
                    {unit.split(" ").slice(-1)[0]}
                  </span>
                )}
              </span>
            </div>
          </div>
        </div>
        {marks.length > 0 && (
          <div className="relative mt-1 h-5 text-[11.5px]">
            {marks.map((m) => (
              <button
                key={m.value}
                type="button"
                tabIndex={-1}
                onClick={() => {
                  setThrown(true);
                  set(m.value);
                }}
                className={`cursor-pointer absolute -translate-x-1/2 whitespace-nowrap transition-colors duration-300 hover:text-foreground ${value >= m.value ? "text-foreground" : "text-muted-foreground"}`}
                style={{ left: `${toRatio(m.value) * 100}%` }}
              >
                {m.label}
              </button>
            ))}
          </div>
        )}
      </div>

      {cta && (
        <div className="mt-8">
          <button
            type="button"
            onClick={() =>
              cta.onClick?.(value, contact ? "Enterprise" : planName, billing)
            }
            className={`cursor-pointer inline-flex h-10 items-center justify-center rounded-full px-5 text-[13.5px] font-medium transition-[background-color,color,box-shadow,transform] duration-300 active:scale-[0.97] ${FOCUS} ${
              contact
                ? "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                : "bg-primary text-primary-foreground hover:bg-primary/90"
            }`}
          >
            <TextMorph>
              {contact
                ? (cta.contactLabel ?? "Contact sales")
                : cta.label(planName)}
            </TextMorph>
          </button>
        </div>
      )}
      <p id={`${id}-plan`} className="sr-only" aria-live="polite">
        {contact ? "Contact sales for this size" : `${planName} plan`}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PRICING TOGGLE: monthly or yearly, and every price rolls
 *
 *   toggle   the thumb slides and resizes to the chosen option
 *            with a little give; the labels trade colour
 *   badge    "Save 20%" sits inside Yearly and lights up in
 *            your brand colour when it's chosen
 *   prices   Price rolls each figure to its new amount, and the
 *            billing line crossfades in the direction you went
 *
 * PricingToggle is the control; Price is the number. Use them
 * together across your plan columns.
 * ───────────────────────────────────────────────────────── */

export interface BillingOption {
  value: string;
  label: string;
  /** e.g. "Save 20%". */
  badge?: string;
}

export interface PricingToggleProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  value: string;
  onValueChange: (value: string) => void;
  options?: BillingOption[];
  label?: string;
}

export interface PriceProps extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
  currency?: string;
  /** Format in this locale everywhere. Without it, a server render and hydration use en-US and the visitor's locale takes over after mount. */
  locales?: string | string[];
  /** e.g. "/mo"; hidden for free plans. */
  period?: string;
  /** A line under the price, e.g. "$288 billed yearly". */
  note?: string;
  /** Which way the toggle moved (1 or -1), so the note slides with it. */
  direction?: number;
  /** Classes for the figure, e.g. its size. */
  numberClassName?: string;
}

const BILLING: BillingOption[] = [
  { value: "monthly", label: "Monthly" },
  { value: "yearly", label: "Yearly", badge: "Save 20%" },
];
// A little give at the end of the slide, so the thumb feels like it was thrown, not placed.
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function PricingToggle({
  value,
  onValueChange,
  options = BILLING,
  label = "Billing period",
  className = "",
  ...props
}: PricingToggleProps) {
  const reduced = useReducedMotion();
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });
  const active = Math.max(
    0,
    options.findIndex((o) => o.value === value),
  );

  React.useLayoutEffect(() => {
    const measure = () => {
      const el = refs.current[active];
      if (!el) return;
      const left = el.offsetLeft;
      const width = el.offsetWidth;
      setThumb((t) =>
        t.left === left && t.width === width
          ? t
          : { left, width, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    refs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [active, options]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    const next =
      (active + (e.key === "ArrowRight" ? 1 : -1) + options.length) %
      options.length;
    onValueChange(options[next].value);
    refs.current[next]?.focus();
  };

  return (
    <div
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative inline-flex items-center rounded-full border border-border bg-muted/60 p-1 ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="absolute inset-y-1 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          width: thumb.width,
          transform: `translateX(${thumb.left}px)`,
          transition:
            thumb.ready && !reduced
              ? `transform 520ms ${THROW}, width 420ms ${EASE}`
              : "none",
        }}
      />
      {options.map((option, i) => {
        const selected = i === active;
        return (
          <button
            key={option.value}
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            onClick={() => onValueChange(option.value)}
            className={`cursor-pointer relative flex h-8 items-center gap-2 rounded-full px-3.5 text-[13px] font-medium transition-colors duration-300 ${FOCUS} ${
              selected
                ? "text-foreground"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {option.label}
            {option.badge && (
              <span
                className={`rounded-full px-1.5 py-px text-[11px] font-medium transition-[background-color,color] duration-300 ${
                  selected
                    ? "bg-primary text-primary-foreground"
                    : "bg-primary/10 text-primary"
                }`}
              >
                {option.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function Price({
  amount,
  currency = "USD",
  locales,
  period = "/mo",
  note,
  direction = 1,
  numberClassName = "text-[40px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground",
  className = "",
  ...props
}: PriceProps) {
  const format = React.useMemo<Intl.NumberFormatOptions>(
    () => ({
      style: "currency",
      currency,
      maximumFractionDigits: amount % 1 ? 2 : 0,
      minimumFractionDigits: amount % 1 ? 2 : 0,
    }),
    [currency, amount],
  );
  return (
    <div className={className} {...props}>
      <div className="flex items-baseline gap-1">
        <NumberRoll
          value={amount}
          format={format}
          locales={locales}
          className={numberClassName}
        />
        {amount > 0 && period && (
          <span className="text-[14px] text-muted-foreground">{period}</span>
        )}
      </div>
      {note !== undefined && (
        <div className="relative mt-1 h-5 overflow-hidden text-[12.5px] text-muted-foreground">
          <span
            key={note}
            className="absolute inset-0 truncate motion-safe:animate-[ui-note-in_380ms_cubic-bezier(0.23,1,0.32,1)_both]"
            style={
              {
                "--ui-from": `${direction > 0 ? 100 : -100}%`,
              } as React.CSSProperties
            }
          >
            {note}
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

